/// A file the command line named could not be opened or read: which file, and why when the OS says.
fn file_error(flag: &str, path: &str, e: &std::io::Error) -> String {
    if e.kind() == std::io::ErrorKind::NotFound { format!("{flag}: 找不到文件 {path}") } else { format!("{flag}: 打不开 {path}，{e}") }
}
